INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.127.0',
  '2026-11-04',
  'Пульт ТВ: теги файлов, фильтр и подборки по тегам, поиск, субтитры',
  E'Файлам и папкам можно ставить теги — например, #отпуск или #любимое. Теги задаются в карандаше ✏ (с подсказками из тех, что уже есть) или разом нескольким файлам: «☐ Выбрать», отметить нужные, «🏷 Теги выбранным».\n\nНад списком папки — все её теги с числом файлов. Нажатие на тег оставляет только файлы с ним, можно выбрать несколько. Такой фильтр можно сохранить подборкой — она появится плиткой на главной визуального режима, в разделе «Подборки по тегам».\n\nКнопка «🔍 Поиск» ищет по названию, заголовку и тегам — в текущей папке или по всей медиатеке. Папку можно упорядочить по имени, дате, размеру или типу, у фотографий в списке видно превью.\n\nСубтитры, которые лежат рядом с фильмом (файл .srt с тем же именем), подключаются сами — включаются кнопкой «💬» в плеере.',
  E'Медиаагент: `tags.go` — теги в `fileMeta.Tags` (`normTags`), `POST /api/file/tags`, `GET /api/tags`, `GET /api/search` (по снимку индекса и `metaStore`, лимит 300, `where`), подборки `tagviews.json` (`POST/DELETE /api/tagviews`, `catalogData.TagViews`, область по пути, в `moveMemory`); `/api/file/edit` принимает `tags`; теги в `decorate`, `applyTitles`, `/api/photos`, `/api/tracks`. `subs.go` — `.srt/.vtt` рядом с видео в `outItem.Subs` (`attachSubs` в `withURLs`), `/subs/{id}` → WebVTT (SRT и cp1251 на лету). Страница: облако тегов и фильтр (`allItems`/`applyView`), порядок `htv.fsort`, выбор и массовые теги, поиск и подборки уровнями стека «Файлов», превью снимков, `<track>` и кнопка «💬» (`htv.subs`).'
);
-- +goose StatementEnd

